from future.utils import with_metaclass

from abc import ABCMeta, abstractmethod
import os
import subprocess
from ute_common_config_files.scfc.scfc import Scfc


class SUToolReturnCode(int):
    def _is_bit_set(self, number):
        return self & (1 << number)

    @property
    def invalid_args_or_parsing_failed(self):
        """Returns trus if this return code indicates a problem with arguments or input SCFC."""
        return self == 0xFF

    @property
    def at_least_one_merged(self):
        """Returns trus if SUTool applied at least one rule file to input SCFC."""
        return not self.invalid_args_or_parsing_failed and self._is_bit_set(0)

    @property
    def at_least_one_faulty(self):
        """Not sure what this means."""  # TODO
        return not self.invalid_args_or_parsing_failed and self._is_bit_set(1)

    @property
    def sw_fallback_needed(self):
        """Not sure what this means."""  # TODO
        return not self.invalid_args_or_parsing_failed and self._is_bit_set(2)

    @property
    def no_rule_files_found(self):
        """Returns true if SUTool found no rule files in the specified directory.."""
        return not self.invalid_args_or_parsing_failed and self._is_bit_set(3)


class SUTool(object):

    DEFAULT_INSTALLATION_DIR = '/opt/sutool'

    def __new__(cls, installation_dir=DEFAULT_INSTALLATION_DIR):
        for klass in SUTool_1_2, SUTool_1_0:
            if klass._is_installed(installation_dir):
                return klass(installation_dir)
        raise InvalidSUToolInstallation(installation_dir)


class SUToolBase(with_metaclass(ABCMeta, object)):

    OUT_LOGS_FILE = 'SUTool_stdout.log'

    def __init__(self, installation_dir):
        self.installation_dir = installation_dir

    def migrate_scfc_locally(self, scfc_path, output_path, rules_dir='.', log_path='', adaptation_versions_path=None):
        """Runs SUTool on the virtual machine (not on eNB) with given parameters and returns the return code."""
        self._validate_args(scfc_path, adaptation_versions_path)
        command = self._get_command(scfc_path, output_path, rules_dir, log_path, adaptation_versions_path)
        stdout_logs_path = self._get_stdout_logs_path(log_path)
        with open(stdout_logs_path, 'w+') as out_logs_path:
            rc = subprocess.call(command, shell=True, stdout=out_logs_path, stderr=subprocess.STDOUT)
        return SUToolReturnCode(rc)

    def _get_stdout_logs_path(self, log_path):
        return os.path.dirname(log_path) + '/' + self.OUT_LOGS_FILE if log_path else os.devnull

    @classmethod
    def _is_installed(cls, installation_dir):
        raise NotImplementedError

    @abstractmethod
    def _get_command(self, scfc_path, output_path, rules_dir, log_path, adaptation_versions_path):
        pass

    @abstractmethod
    def _validate_args(self, scfc_path, adaptation_versions_path):
        pass

    def _scfc_uses_new_versioning(self, scfc_path):
        """Note: MO class prefixes and new versioning system were introduced together
           and prefixes are easier to check"""
        return ':' in Scfc(scfc_path).find_all_managed_objects()[0].klass

    @classmethod
    def _file_exists(cls, template, **params):
        return os.path.isfile(template.format(**params))


class SUTool_1_0(SUToolBase):
    """Legacy installation - for ute-sutool==1.0. Supports only SCFCs not using the new versioning system."""

    EXECUTABLE = '{installation_dir}/ScfUpgrade'
    COMMAND = '{executable} {scfc_path} {output_path} {rules_dir} {log_path}'

    @classmethod
    def _is_installed(cls, installation_dir):
        return cls._file_exists(cls.EXECUTABLE, installation_dir=installation_dir)

    def _get_command(self, scfc_path, output_path, rules_dir, log_path, adaptation_versions_path):
        executable = self.EXECUTABLE.format(installation_dir=self.installation_dir)
        command = self.COMMAND.format(
            executable=executable, scfc_path=scfc_path, output_path=output_path, rules_dir=rules_dir, log_path=log_path
        )
        return command.strip()

    def _validate_args(self, scfc_path, adaptation_versions_path):
        if self._scfc_uses_new_versioning(scfc_path):
            raise SUToolUpdateNeeded('New FL/TL17+ SCFCs are not supported by this version of SUTool')
        if adaptation_versions_path is not None:
            raise SUToolUpdateNeeded('AdaptationVersions file is not supported by this version of SUTool')


class SUTool_1_2(SUToolBase):
    """Double installation - for ute-sutool==1.2. Supports both SCFCs
       using the new versioning system and the old ones."""

    BRANCH_EXECUTABLE = '{installation_dir}/16/ScfUpgrade'
    BRANCH_COMMAND = '{executable} {scfc_path} {output_path} {rules_dir} {log_path}'

    TRUNK_EXECUTABLE = '{installation_dir}/17/ScfUpgrade'
    TRUNK_COMMAND = '{executable} {scfc_path} {output_path} {adaptation_versions_path} {rules_dir} {log_path}'

    @classmethod
    def _is_installed(cls, installation_dir):
        return cls._file_exists(cls.BRANCH_EXECUTABLE, installation_dir=installation_dir) and cls._file_exists(
            cls.TRUNK_EXECUTABLE, installation_dir=installation_dir
        )

    def _validate_args(self, scfc_path, adaptation_versions_path):
        if self._scfc_uses_new_versioning(scfc_path) and adaptation_versions_path is None:
            raise InvalidSUToolInput(
                'AdaptationVersions file should be specified if input SCFC uses the new versioning system'
            )

    def _get_command(self, scfc_path, output_path, rules_dir, log_path, adaptation_versions_path):
        if adaptation_versions_path is not None:
            executable_template, command_template = self.TRUNK_EXECUTABLE, self.TRUNK_COMMAND
        else:
            executable_template, command_template = self.BRANCH_EXECUTABLE, self.BRANCH_COMMAND

        executable = executable_template.format(installation_dir=self.installation_dir)
        command = command_template.format(
            executable=executable,
            scfc_path=scfc_path,
            output_path=output_path,
            rules_dir=rules_dir,
            log_path=log_path,
            adaptation_versions_path=adaptation_versions_path,
        )
        return command.strip()


class SUToolException(Exception):
    """Base class for SUTool-related exceptions"""


class ScfcParsingFailedOrInvalidSUToolArgs(SUToolException):
    """An exception representing return code 255 (invalid arguments or parsing failed)"""


class NoScfdRuleFilesFound(SUToolException):
    """An exception representing return codes 12-15 / bit #3 set (noRuleFilesFound)"""


class InvalidSUToolInstallation(SUToolException):
    """Raised when SUTool is not properly installed at given path"""

    def __init__(self, installation_dir):
        if os.path.isdir(installation_dir):
            self.message = 'Cannot find SUTool executable (ScfUpgrade) in ' + installation_dir
        else:
            self.message = 'Installation dir ' + installation_dir + ' does not exist'


class SUToolUpdateNeeded(SUToolException):
    """Raised when SUTool is run with SCFC or other parameters that are not supported in the installed version"""


class InvalidSUToolInput(SUToolException):
    """Raised when SUTool is run with incorrect parameters"""
